import copy, hashlib, json, math, platform, time
from pathlib import Path
from quantage.core import understand, formulate, solve_qubo, optical_probabilities, pipeline
from quantage.verification import verify
path = Path("runs/20261113-c05-semantic-contracts/audit_cases.json")
doc = json.loads(path.read_text())
def decode(value):
    if isinstance(value, dict):
        if set(value) == {"$float"}: return float(value["$float"])
        return {k:decode(v) for k,v in value.items()}
    if isinstance(value, list): return [decode(v) for v in value]
    return value
def encode(value):
    if isinstance(value, float) and not math.isfinite(value): return {"$float": "nan" if math.isnan(value) else "inf" if value > 0 else "-inf"}
    if isinstance(value, dict): return {k:encode(v) for k,v in value.items()}
    if isinstance(value, (list,tuple)): return [encode(v) for v in value]
    return value
def hashes():
    return {s:hashlib.sha256(Path(s).read_bytes()).hexdigest() for s in doc["audited_files"]}
started=time.perf_counter(); before=hashes(); rows=[]
for raw in doc["cases"]:
    case=decode(raw)
    if case["mode"] == "pipeline":
        result={"id":case["id"],"pipeline":pipeline(case["request"])}
    else:
        problem=understand(case["request"]); problem.update(case.get("problem_updates",{}))
        model=formulate(understand(case["request"]));model.update(case.get("model_updates",{}))
        check=verify(problem,model,tolerance=case.get("tolerance",1e-12))
        try:
            solution=solve_qubo(model) if problem["family"] == "mis" else {"probabilities":optical_probabilities(model)}
        except Exception as exc: solution={"exception":type(exc).__name__,"message":str(exc)}
        result={"id":case["id"],"problem":problem,"proposal":model,"verification":check,"solution":solution}
        if "hand_expected_solutions" in case:
            result["hand_control_pass"] = solution.get("solutions") == case["hand_expected_solutions"]
        if "hand_expected_probabilities" in case:
            actual=solution.get("probabilities",[])
            result["hand_control_error"] = max(abs(a-b) for a,b in zip(actual,case["hand_expected_probabilities"]))
            result["hand_control_pass"] = len(actual)==2 and result["hand_control_error"] <= 1e-12
    rows.append(result)
print(json.dumps(encode({"results":rows,"input_hashes_before":before,"input_hashes_after":hashes(),"runtime_seconds":time.perf_counter()-started,"python":platform.python_version(),"platform":platform.platform()}),sort_keys=True,allow_nan=False))
